/* eslint-disable */
import React from "react";

export default function PrettyCalendar({
    year = 2023,
    month = 2,           // 1..12
    selectedDay = 20,
    title = "Un jour spécial pour ?",
    birthdayLabel = "Anniversaire de Ousmane DIA",
}) {
    const monthIndex = month - 1;
    const monthName = new Date(year, monthIndex, 1).toLocaleString("fr-FR", { month: "long" });
    const firstWeekday = new Date(year, monthIndex, 1).getDay();   // 0=dim..6=sam
    const daysInMonth = new Date(year, month, 0).getDate();

    // cellules: vides avant le 1er + jours du mois, puis on complète à /7
    const cells = [
        ...Array(firstWeekday).fill(null),
        ...Array.from({ length: daysInMonth }, (_, i) => i + 1),
    ];
    while (cells.length % 7 !== 0) cells.push(null);

    const week = ["SUN", "MON", "TUE", "WED", "THU", "FRI", "SAT"];

    return (
        <div className="w-full max-w-sm mx-auto">
            <h3 className="text-[#1c2b68] font-semibold text-2xl mb-3">{title}</h3>

            <div className="bg-white rounded-2xl shadow-md p-5">
                {/* Mois */}
                <div className="text-center uppercase tracking-wide text-blueGray-500 text-xl mb-3">
                    {monthName} {year}
                </div>

                {/* Bandeau jours (pilule grise) */}
                <div className="bg-blueGray-100 rounded-full px-3 py-2">
                    <div className="grid grid-cols-7 text-center text-[11px] font-semibold">
                        {week.map((d, i) => (
                            <div key={d} className={i === 0 ? "text-red-500" : "text-blueGray-500"}>
                                {d}
                            </div>
                        ))}
                    </div>
                </div>

                {/* Grille des dates */}
                <div className="mt-4 grid grid-cols-7 gap-y-3">
                    {cells.map((v, idx) => {
                        const isSelected = v === selectedDay && v !== null;
                        const isSunday = (idx % 7) === 0;

                        return (
                            <div key={idx} className="flex items-center justify-center h-8">
                                {v ? (
                                    <div
                                        className={`w-8 h-8 flex items-center justify-center ${isSelected ? "bg-[#e8b6b6] rounded-md" : ""
                                            }`}
                                    >
                                        <span className={`text-sm ${isSelected ? "text-[#6b1410]" :
                                                isSunday ? "text-red-500" : "text-blueGray-700"
                                            }`}>
                                            {v}
                                        </span>
                                    </div>
                                ) : (
                                    <span className="text-blueGray-300 select-none">&nbsp;</span>
                                )}
                            </div>
                        );
                    })}
                </div>
            </div>

            {/* Légende */}
            <div className="mt-5 flex items-center justify-between">
                <span className="text-blueGray-800 font-semibold text-lg">
                    {birthdayLabel}
                </span>
                <span role="img" aria-label="party" className="text-2xl">🎉</span>
            </div>
        </div>
    );
}
